//
//html import
//
//------------------------------------------------------
//
//forbidden
//
//index
//this injection name is reserved
declare module '*/index.htm' {
  const value: undefined;
  export default value;
}

//this injection name is reserved
declare module '*/index.html' {
  const value: undefined;
  export default value;
}

//this injection name is reserved
declare module '*/index.xhtml' {
  const value: undefined;
  export default value;
}

//app
//this injection name is reserved
declare module '*/app.htm' {
  const value: undefined;
  export default value;
}

//this injection name is reserved
declare module '*/app.html' {
  const value: undefined;
  export default value;
}

//this injection name is reserved
declare module '*/app.xhtml' {
  const value: undefined;
  export default value;
}

//
//allowed
//
declare module '*.htm' {
  const value: string;
  export default value;
}

declare module '*.html' {
  const value: string;
  export default value;
}

declare module '*.xhtml' {
  const value: string;
  export default value;
}

